#include <iostream>
#include <string>

class ReportTemplate {
public:
    std::string title;
    std::string styling;

    ReportTemplate(std::string title, std::string styling)
        : title(std::move(title)), styling(std::move(styling)) {}

    ReportTemplate clone() const {
        // Build a new instance and copy each field across
        return ReportTemplate(title, styling);
    }
};

int main() {
    ReportTemplate base("Quarterly Report", "corporate-blue");
    ReportTemplate copy = base.clone();

    copy.title = "Quarterly Report, Draft 2";

    std::cout << base.title << std::endl; // Quarterly Report
    std::cout << copy.title << std::endl; // Quarterly Report, Draft 2
    return 0;
}

