import java.util.List;
import java.util.ArrayList;

class ReportTemplate {
    String title;
    List<String> sections;

    ReportTemplate(String title, List<String> sections) {
        this.title = title;
        this.sections = sections; // a list, a nested object
    }

    ReportTemplate cloneShallow() {
        // BUG: sections is the same list reference, not a new list
        return new ReportTemplate(this.title, this.sections);
    }
}

public class Main {
    public static void main(String[] args) {
        ReportTemplate base = new ReportTemplate("Quarterly Report", new ArrayList<>(List.of("Summary", "Charts")));
        ReportTemplate copy = base.cloneShallow();

        copy.sections.add("Appendix");

        System.out.println(base.sections); // [Summary, Charts, Appendix], unexpectedly changed too
        System.out.println(copy.sections); // [Summary, Charts, Appendix]
    }
}

