#include <iostream>
#include <vector>
#include <memory>
#include <string>

class ReportTemplate {
public:
    std::string title;
    std::shared_ptr<std::vector<std::string>> sections;

    ReportTemplate(std::string title, std::shared_ptr<std::vector<std::string>> sections)
        : title(std::move(title)), sections(std::move(sections)) {}

    ReportTemplate cloneShallow() const {
        // BUG: sections is the same shared pointer, not a new vector
        return ReportTemplate(title, sections);
    }
};

void printSections(const std::vector<std::string>& sections) {
    std::cout << "[";
    for (size_t i = 0; i < sections.size(); ++i) {
        std::cout << sections[i];
        if (i + 1 < sections.size()) std::cout << ", ";
    }
    std::cout << "]" << std::endl;
}

int main() {
    ReportTemplate base("Quarterly Report", std::make_shared<std::vector<std::string>>(std::vector<std::string>{"Summary", "Charts"}));
    ReportTemplate copy = base.cloneShallow();

    copy.sections->push_back("Appendix");

    printSections(*base.sections); // [Summary, Charts, Appendix], unexpectedly changed too
    printSections(*copy.sections); // [Summary, Charts, Appendix]
    return 0;
}

