class ReportTemplate {
public:
    std::string title;
    std::vector<std::string> sections;

    ReportTemplate(std::string title, std::vector<std::string> sections)
        : title(std::move(title)), sections(std::move(sections)) {}

    ReportTemplate clone() const {
        // FIX: the vector's copy constructor builds a brand new vector, nothing is shared
        return ReportTemplate(title, sections);
    }
