    ReportTemplate base("Quarterly Report", {"Summary", "Charts"});
    ReportTemplate copy = base.clone();

    copy.sections.push_back("Appendix");

    printSections(base.sections); // [Summary, Charts], untouched
    printSections(copy.sections); // [Summary, Charts, Appendix]
